"""Re-order list given regular expression listed by priorities

    Example:
    --------
    >>> _order_from_regexp(["aA", "aZ", "bb", "bY", "cZ", "aY"], [".*Y", ".*Z"])
    ['bY', 'aY', 'aZ', 'cZ', 'aA', 'bb']
    """
def _order_from_regexp(items: Any, order_regexps: Any) -> object {
    import re;
    ordered = `list();
    for order_regexp in order_regexps {
        matched = [
            item
            for item in items
            if re.search(order_regexp, item)
        ];
        for item in matched {
            ordered.append(item);
            items.remove(item);
        }
    }
    ordered += items;
    return ordered;
}

"""\
    Convert a mapping of distinct quantities to a mapping of proportions of the
    total quantity.
    """
def scale_to_total(value: Any) -> object {
    total = float(sum(value.values()));
    return {k: (v / total) for (k, v) in value.items()};
}

