"""
    Removes extension of the given file path
    For example, C:/test/rig.py will return rig
    :param file_path: str
    :return: str
    """
def remove_extension(file_path: Any) -> object {
    split_path = file_path.split('.');
    new_name = file_path;
    if (len(split_path) > 1) {
        new_name = '.'.join(split_path[:-1]);
    }
    return new_name;
}

"""
    converts string referencing csv file to a json file

    :param csv_filename: (string) name of data, as a csv file
    :return: string of json filename matching csv file
    """
def csv_to_json(csv_filename: Any) -> object {
    csv_trimmed = csv_filename[:-3];
    json_added = csv_trimmed + 'json';
    return json_added;
}

